"""Bernoulli numbers using the Akiyama–Tanigawa algorithm with exact rational arithmetic."""

from fractions import Fraction


def bernoulli(n: int) -> list[Fraction]:
    """Return B(0), B(1), ..., B(n) using the standard convention B(1) = -1/2."""
    if n < 0:
        raise ValueError("n must be non-negative")

    A = [Fraction(0)] * (n + 1)
    B = [Fraction(0)] * (n + 1)

    for m in range(n + 1):
        A[m] = Fraction(1, m + 1)
        for j in range(m, 0, -1):
            A[j - 1] = j * (A[j - 1] - A[j])
        B[m] = A[0]

    # Akiyama–Tanigawa gives B(1) = +1/2; standard convention is B(1) = -1/2
    if n >= 1:
        B[1] = -B[1]

    return B


if __name__ == "__main__":
    for i, b in enumerate(bernoulli(20)):
        print(f"B({i:2d}) = {b}")
